std::vector<AsioPort>asioPorts(){std::vector<AsioPort>ports;HKEY root;if(RegOpenKeyExW(HKEY_LOCAL_MACHINE,L"SOFTWARE\\ASIO",0,KEY_READ|KEY_WOW64_64KEY,&root)!=ERROR_SUCCESS)return ports;wchar_t name[256];for(DWORD index=0;;index++){DWORD size=256;if(RegEnumKeyExW(root,index,name,&size,nullptr,nullptr,nullptr,nullptr)!=ERROR_SUCCESS)break;HKEY key;if(RegOpenKeyExW(root,name,0,KEY_READ,&key)!=ERROR_SUCCESS)continue;wchar_t id[256]{},description[256]{};DWORD bytes=sizeof id;if(RegQueryValueExW(key,L"CLSID",nullptr,nullptr,(BYTE*)id,&bytes)==ERROR_SUCCESS){bytes=sizeof description;RegQueryValueExW(key,L"Description",nullptr,nullptr,(BYTE*)description,&bytes);std::wstring label=description[0]?description:name;if(!_wcsicmp(id,L"{188135E1-7171-3434-854F-01A3C71F3DF9}"))label=L"System Audio ASIO";ports.push_back({id,label});}RegCloseKey(key);}RegCloseKey(root);return ports;}
int asioSampleBytes(int format){int type=format&15;return format>=0&&format<32&&(type<=4||(type>=8&&type<=11))?(type==0?2:type==1?3:type==4?8:4):0;}
float asioReadSample(const void*buffer,int sample,int format){int bytes=asioSampleBytes(format);if(!buffer||!bytes)return 0;auto*p=(const uint8_t*)buffer+sample*bytes;uint64_t raw=0;bool little=format>=16;for(int i=0;i<bytes;i++)raw|=uint64_t(p[i])<<((little?i:bytes-1-i)*8);int type=format&15;double value=0;if(type==3){uint32_t bits=(uint32_t)raw;float f;memcpy(&f,&bits,4);value=f;}else if(type==4)memcpy(&value,&raw,8);else{int significant=type>=8?type==8?16:type==9?18:type==10?20:24:bytes*8;int64_t n=(int64_t)(raw<<(64-significant))>>(64-significant);value=n/std::ldexp(1.,significant-1);}return std::isfinite(value)?(float)clamp(value,-8,8):0;}
void asioWriteSample(void*buffer,int sample,int format,float value){int bytes=asioSampleBytes(format);if(!buffer||!bytes)return;value=(float)clamp(std::isfinite(value)?value:0,-1,1);uint64_t raw=0;int type=format&15;if(type==3){uint32_t bits;memcpy(&bits,&value,4);raw=bits;}else if(type==4){double d=value;memcpy(&raw,&d,8);}else{int significant=type>=8?type==8?16:type==9?18:type==10?20:24:bytes*8;raw=(uint64_t)(int64_t)(value*(std::ldexp(1.,significant-1)-1));}auto*p=(uint8_t*)buffer+sample*bytes;bool little=format>=16;for(int i=0;i<bytes;i++)p[i]=(uint8_t)(raw>>((little?i:bytes-1-i)*8));}
#include "asio_convert.inc"
struct AsioStream::Impl{
    IASIO*driver=nullptr;bool buffersCreated=false,started=false,outputReady=false;double sampleRate=48000;long size=512,inLatency=0,outLatency=0,inCount=0,outCount=0;int openedInputs=0,primaryInput=0;
    std::array<ASIOBufferInfo,66>buffers{};std::array<ASIOChannelInfo,66>channels{};ASIOCallbacks callbacks{};Callback callback=nullptr;Timing timing=nullptr;LARGE_INTEGER counterFrequency{};void*context=nullptr;
    std::array<std::array<float,MaxBlock>,64>inputs{};std::array<const float*,64>inputPointers{};std::array<float,MaxBlock>left{},right{};std::array<float,MaxBlock*2>interleaved{};std::atomic<bool>restart{false};static std::atomic<Impl*>current;
    ~Impl(){if(driver){if(started)driver->stop();Impl*expected=this;current.compare_exchange_strong(expected,nullptr);if(buffersCreated)driver->disposeBuffers();driver->Release();}}
    static void switchBuffer(long index,ASIOBool){auto*self=current.load();if(!self||index<0||index>1)return;LARGE_INTEGER begin,end;QueryPerformanceCounter(&begin);for(int c=0;c<self->openedInputs;c++){asioReadBlock(self->buffers[c].buffers[index],self->inputs[self->channels[c].channel].data(),self->size,self->channels[c].type);self->inputPointers[self->channels[c].channel]=self->inputs[self->channels[c].channel].data();}const float*l=self->primaryInput>=0&&self->primaryInput<std::min(64,(int)self->inCount)?self->inputPointers[self->primaryInput]:nullptr,*r=self->primaryInput>=0&&self->primaryInput+1<std::min(64,(int)self->inCount)?self->inputPointers[self->primaryInput+1]:l;
        self->callback(self->context,l,r,self->interleaved.data(),self->size,self->inputPointers.data(),std::min(64,(int)self->inCount));for(int c=0;c<2;c++){int channel=self->openedInputs+c;asioWriteBlock(self->buffers[channel].buffers[index],self->interleaved.data(),c,self->size,self->channels[channel].type);}if(self->outputReady)self->driver->outputReady();QueryPerformanceCounter(&end);if(self->timing)self->timing(self->context,self->size,(end.QuadPart-begin.QuadPart)/double(self->counterFrequency.QuadPart));}
    static ASIOTime*timeBuffer(ASIOTime*time,long index,ASIOBool direct){switchBuffer(index,direct);return time;}
    static void changedRate(ASIOSampleRate){if(auto*self=current.load())self->restart=true;}
    static long message(long selector,long value,void*,double*){if(selector==kAsioSelectorSupported)return value==kAsioEngineVersion||value==kAsioResetRequest||value==kAsioResyncRequest||value==kAsioLatenciesChanged||value==kAsioSupportsTimeInfo;if(selector==kAsioEngineVersion)return 2;if(selector==kAsioSupportsTimeInfo)return 1;if(selector==kAsioResetRequest||selector==kAsioResyncRequest||selector==kAsioLatenciesChanged){if(auto*self=current.load())self->restart=true;return 1;}return 0;}
};
std::atomic<AsioStream::Impl*>AsioStream::Impl::current{nullptr};
AsioStream::AsioStream()=default;AsioStream::~AsioStream()=default;
void AsioStream::open(const std::wstring&id,double requestedRate,int requestedFrames,int inputPair,int outputPair,HWND window,Callback callback,void*context,Timing timing,uint64_t inputMask){impl=std::make_unique<Impl>();auto&h=*impl;CLSID clsid;if(FAILED(CLSIDFromString(id.c_str(),&clsid))||FAILED(CoCreateInstance(clsid,nullptr,CLSCTX_INPROC_SERVER,clsid,(void**)&h.driver)))throw std::runtime_error("Cannot open installed 64-bit ASIO driver");if(!h.driver->init(window)){char error[256]{};h.driver->getErrorMessage(error);throw std::runtime_error(std::string("ASIO initialization: ")+error);}if(h.driver->getChannels(&h.inCount,&h.outCount)!=ASE_OK||h.outCount<2)throw std::runtime_error("ASIO driver needs a stereo output");
    if(requestedRate>0&&h.driver->setSampleRate(requestedRate)!=ASE_OK)throw std::runtime_error("ASIO does not support the selected sample rate");if(h.driver->getSampleRate(&h.sampleRate)!=ASE_OK||h.sampleRate<8000||h.sampleRate>384000)throw std::runtime_error("Invalid ASIO sample rate");long minimum=0,maximum=0,preferred=0,granularity=0;if(h.driver->getBufferSize(&minimum,&maximum,&preferred,&granularity)!=ASE_OK)throw std::runtime_error("ASIO buffer information unavailable");h.size=requestedFrames?requestedFrames:preferred;h.size=std::max(minimum,std::min(maximum,h.size));if(granularity==-1){long power=1;while(power<h.size&&power<MaxBlock)power*=2;h.size=power;}else if(granularity>0)h.size=minimum+((h.size-minimum+granularity-1)/granularity)*granularity;h.size=std::min(h.size,maximum);if(h.size<1||h.size>MaxBlock)throw std::runtime_error("ASIO buffer must be 1–4096 samples");
    h.primaryInput=inputPair;if(inputPair>=0)inputMask|=inputChannelMask(inputPair);std::array<int,64>selectedInputs{};for(int c=0;c<std::min(64,(int)h.inCount);c++)if(inputMask&(1ull<<c))selectedInputs[h.openedInputs++]=c;if(inputPair>=0&&!h.openedInputs&&h.inCount)throw std::runtime_error("Selected ASIO input does not exist");if(outputPair<0||outputPair+1>=h.outCount)throw std::runtime_error("Selected ASIO output pair does not exist");for(int i=0;i<h.openedInputs+2;i++){bool input=i<h.openedInputs;h.buffers[i].isInput=input;h.buffers[i].channelNum=input?selectedInputs[i]:outputPair+i-h.openedInputs;h.channels[i].channel=h.buffers[i].channelNum;h.channels[i].isInput=input;if(h.driver->getChannelInfo(&h.channels[i])!=ASE_OK||!asioSampleBytes(h.channels[i].type))throw std::runtime_error("Unsupported ASIO channel format");}
    h.callback=callback;h.context=context;h.timing=timing;QueryPerformanceFrequency(&h.counterFrequency);h.callbacks={Impl::switchBuffer,Impl::changedRate,Impl::message,Impl::timeBuffer};if(h.driver->createBuffers(h.buffers.data(),h.openedInputs+2,h.size,&h.callbacks)!=ASE_OK)throw std::runtime_error("ASIO could not create audio buffers");h.buffersCreated=true;for(int b=0;b<2;b++)for(int i=h.openedInputs;i<h.openedInputs+2;i++)memset(h.buffers[i].buffers[b],0,h.size*asioSampleBytes(h.channels[i].type));h.driver->getLatencies(&h.inLatency,&h.outLatency);h.outputReady=h.driver->outputReady()==ASE_OK;
}
void AsioStream::start(){if(!impl)throw std::runtime_error("ASIO is not open");Impl*expected=nullptr;if(!Impl::current.compare_exchange_strong(expected,impl.get()))throw std::runtime_error("Another ASIO stream is active");if(impl->driver->start()!=ASE_OK){Impl::current=nullptr;throw std::runtime_error("ASIO stream start failed");}impl->started=true;}
void AsioStream::panel(){if(impl)impl->driver->controlPanel();}bool AsioStream::restartNeeded()const{return impl&&impl->restart.load();}double AsioStream::rate()const{return impl->sampleRate;}int AsioStream::frames()const{return impl->size;}int AsioStream::inputLatency()const{return impl->inLatency;}int AsioStream::outputLatency()const{return impl->outLatency;}int AsioStream::inputs()const{return impl->inCount;}int AsioStream::outputs()const{return impl->outCount;}
